(function(){try{var i=typeof window<"u"?window:typeof global<"u"?global:typeof globalThis<"u"?globalThis:typeof self<"u"?self:{},a=new i.Error().stack;a&&(i._sentryDebugIds=i._sentryDebugIds||{},i._sentryDebugIds[a]="58664fc4-fd9d-4e0e-8a00-d388659a897b",i._sentryDebugIdIdentifier="sentry-dbid-58664fc4-fd9d-4e0e-8a00-d388659a897b")}catch{}})();var t="Yhteisön käytännesäännöt",e={p1:"Me kaikki rakastamme musiikkia! Kuten missä tahansa yhteisössä, meillä on käyttäytymissäännöt, joilla pidämme yllä harmoniaa ja hyvää henkeä sekä varmistamme, että kaikilla on täällä mukava olla. Rakennetaan yhdessä ystävällinen ilmapiiri, joka inspiroi meitä luomaan."},n={p1:"Yhteiseloa ohjaavat periaatteet:",p2:"Kunnioitus",p3:"Yhteisöllisyys",p4:"Yhdenvertaisuus"},s={p1:"Odotettu käytös:",p2:"Kohtele kaikkia jäseniä kunnioittavasti.",p3:"Rakentava palaute on tervetullutta.",p4:"Kyse on musiikista, joten pidetään kommentit ja sisältö vain musiikkiin liittyvinä.",p5:"Kohtele muita niin kuin haluaisit itseäsi kohdeltavan."},o={p1:"Hyväksymätön käytös (voimme poistaa tilisi ilman ennakkovaroitusta):",p2:"Muiden tekijöiden epäasiallinen tai loukkaava kohtelu.",p3:"Roskaposti.",p4:"Seksuaalisen sisällön jakaminen.",p5:"Kommentit, joiden tarkoitus on halventaa, loukata tai ärsyttää ketään yhteisön jäsentä."},l={p1:"Toimenpiteet:"},k={p1:"Syyt välittömään porttikieltoon:",p2:"Kaikenlaisen seksuaalisen sisällön jakaminen (kuvat, kommentit ym.).",p3:"Väkivaltaan, rasismiin, muukalaisvihaan, homofobiaan, seksismiin jne. yllyttävän sisällön jakaminen tai sellaisten kommenttien julkaiseminen.",p4:"Muiden käyttäjien roskapostittaminen."},m={p1:"Muut ei-hyväksyttävän käytöksen muodot:",p2:"Loukkaaminen tai halventavien kommenttien julkaiseminen kenestä tahansa yhteisön jäsenestä:",p3:"1. kerta: estämme mahdollisuuden kommentoida toistaiseksi.",p4:"Toisella kerralla: poistamme kommentointioikeutesi pysyvästi tai poistamme tilisi.",p5:"Tukikanavien roskapostitus:",p6:"Tukitiimimme auttaa mielellään, kunhan otat meihin yhteyttä asiallisesti ja vain alustaamme koskevissa asioissa. Epäkunnioittava tai roskapostimainen käytös ei ole tervetullutta ja voi johtaa tilisi poistamiseen."},u={p1:"Mitä tarkoitetaan epäkunnioittavalla kommentilla?",p2:"Tällainen kommentti on yleensä asiaankuulumaton, sopimaton, vahingollinen tai vain häiritsevä. Kirjoittaja ei tee sitä hyvässä hengessä, ja tarkoituksena on saada toinen osapuoli tuntemaan olonsa huonoksi tai nöyryytetyksi.",p3:"Jos et ole varma, onko kommenttisi epäkunnioittava vai ei, jätä se julkaisematta ja etsi kunnioittava ja sivistynyt tapa ilmaista itseäsi."},v={title:t,s1:e,s2:n,s3:s,s4:o,s5:l,s6:k,s7:m,s8:u};export{v as default,e as s1,n as s2,s as s3,o as s4,l as s5,k as s6,m as s7,u as s8,t as title};

